#[test]
fn knowledge_and_history_gc_advance_through_tombstones_without_rolling_back_expiry() {
    let dir = tempfile::tempdir().unwrap();
    let store = Store::open(
        dir.path(),
        Options {
            max_scan: 8,
            ..Default::default()
        },
    )
    .unwrap();
    let t = store
        .tenant(store.create_tenant("gc-tombstone-heads").unwrap().id)
        .unwrap();
    t.identity_initialize(&actor(), IdentityConfig::default())
        .unwrap();
    t.set_retention(60).unwrap();
    drop(store);
    let collection = t
        .engine()
        .transact(|tx| {
            let c: Collection = parse(&tx.get(&named(b"C", COLLECTION))?.unwrap())?;
            Ok(c.id)
        })
        .unwrap();
    let mut state = serde_json::to_value(gc::State::default()).unwrap();
    state["migration_phase"] = json!(5);
    t.engine()
        .transact(|tx| {
            put(tx, STATE.to_vec(), &state)?;
            for n in 1u64..=128 {
                tx.delete(key(KNOWLEDGE, &n.to_be_bytes()))?;
                tx.delete(document_key(collection, &format!("history:a:{:016x}", !n)))?;
            }
            put(tx, key(KNOWLEDGE, &200u64.to_be_bytes()), &Uuid::new_v4())?;
            for ordinal in [100u64, 50] {
                tx.put(
                    document_key(collection, &format!("history:z:{:016x}", !ordinal)),
                    b"baseline".to_vec(),
                )?;
            }
            tx.put(b"Z-expired".to_vec(), b"expired".to_vec())?;
            schedule_at(tx, b"Z-expired", 0, Expiration::Delete)
        })
        .unwrap();
    t.retention_step().unwrap();
    assert!(
        t.engine()
            .snapshot()
            .unwrap()
            .get(b"Z-expired", &mut ReadStats::default())
            .unwrap()
            .is_none()
    );
    for _ in 0..80 {
        t.retention_step().unwrap();
    }
    let snapshot = t.engine().snapshot().unwrap();
    assert!(
        snapshot
            .get(
                &document_key(collection, &format!("history:z:{:016x}", !100u64)),
                &mut ReadStats::default()
            )
            .unwrap()
            .is_some()
    );
    assert!(
        snapshot
            .get(
                &document_key(collection, &format!("history:z:{:016x}", !50u64)),
                &mut ReadStats::default()
            )
            .unwrap()
            .is_none()
    );
    let state: Value = parse(
        &snapshot
            .get(STATE, &mut ReadStats::default())
            .unwrap()
            .unwrap(),
    )
    .unwrap();
    assert_eq!(state["swept_floor"], 200);
}

#[test]
fn retention_migration_pages_physical_records_instead_of_stalling_at_tombstones() {
    let dir = tempfile::tempdir().unwrap();
    let store = Store::open(
        dir.path(),
        Options {
            max_scan: 8,
            ..Default::default()
        },
    )
    .unwrap();
    let t = store
        .tenant(store.create_tenant("migration-tombstones").unwrap().id)
        .unwrap();
    t.set_retention(60).unwrap();
    drop(store);
    t.engine()
        .transact(|tx| {
            for n in 0..128 {
                tx.delete(format!("R{n:04}").into_bytes())?;
            }
            tx.put(b"Rz-live".to_vec(), b"receipt".to_vec())
        })
        .unwrap();
    for _ in 0..40 {
        t.retention_step().unwrap();
    }
    let snapshot = t.engine().snapshot().unwrap();
    let state: Value = parse(
        &snapshot
            .get(STATE, &mut ReadStats::default())
            .unwrap()
            .unwrap(),
    )
    .unwrap();
    assert_eq!(state["migration_phase"], 5);
    assert!(
        snapshot
            .get(&key(DEADLINE, b"Rz-live"), &mut ReadStats::default())
            .unwrap()
            .is_some()
    );
}

#[test]
    fn query_deadline_does_not_become_a_total_write_or_maintenance_deadline() {
        let dir = tempfile::tempdir().unwrap();
        let store = crate::Store::open(
            dir.path(),
            Options {
                query_ms: 10,
                ..Default::default()
            },
        )
        .unwrap();
        let tenant = store
            .tenant(store.create_tenant("write-deadline").unwrap().id)
            .unwrap();
        let engine = tenant.engine().clone();
        drop(tenant);
        drop(store);
        for maintenance in [false, true] {
            let work = |tx: &mut Transaction<'_>| {
                tx.put(b"before".to_vec(), b"confirmed".to_vec())?;
                std::thread::sleep(Duration::from_millis(30));
                assert_eq!(tx.get(b"before")?.unwrap().as_slice(), b"confirmed");
                tx.put(b"after".to_vec(), b"confirmed".to_vec())
            };
            if maintenance {
                engine.transact_maintenance(work).unwrap();
            } else {
                engine.transact(work).unwrap();
            }
        }
        let snapshot = engine.snapshot().unwrap();
        assert_eq!(
            snapshot
                .get(b"after", &mut ReadStats::default())
                .unwrap()
                .unwrap()
                .as_slice(),
            b"confirmed"
        );
    }

#[test]
    fn a_tenant_backup_lock_does_not_block_another_tenants_backup() {
        let dir = tempfile::tempdir().unwrap();
        let store = Store::open(dir.path(), Options::default()).unwrap();
        let a = store.create_tenant("backup-lock-a").unwrap().id;
        let b = store.create_tenant("backup-lock-b").unwrap().id;
        let backup = store.backup(a).unwrap();
        let lock = store.local_backup_lock(a).unwrap();
        let held = lock.lock();
        let deleting = store.clone();
        let delete = thread::spawn(move || deleting.delete_backup(a, backup));
        let backing_up = store.clone();
        let (send, receive) = std::sync::mpsc::channel();
        let other = thread::spawn(move || send.send(backing_up.backup(b)).unwrap());
        let completed = receive.recv_timeout(Duration::from_secs(2));
        assert!(store.root().join(format!("backups/{a}/{backup}")).exists());
        drop(held);
        delete.join().unwrap().unwrap();
        other.join().unwrap();
        completed
            .expect("another tenant waited for the backup lock")
            .unwrap();
    }

#[test]
    fn failed_management_drain_preserves_snapshots_and_does_not_pin_node_authority() {
        let dir = tempfile::tempdir().unwrap();
        let store = Store::open(dir.path(), Options::default()).unwrap();
        let info = store.create_tenant("quota-drain").unwrap();
        let tenant = store.tenant(info.id).unwrap();
        tenant.create_collection("docs").unwrap();
        let ack = tenant
            .put(
                "docs",
                serde_json::json!({"_key":"confirmed","value":1}),
                None,
            )
            .unwrap();
        let snapshot = tenant.engine().snapshot().unwrap();
        store.owner.stop.store(true, Ordering::Release);
        for worker in store.owner.workers.lock().drain(..) {
            worker.join().unwrap();
        }
        let changing = store.clone();
        let quota =
            thread::spawn(move || changing.set_quota(info.id, info.memory_bytes, info.disk_bytes));
        let deadline = Instant::now() + Duration::from_secs(1);
        while store.slot(info.id).lock().installing.is_none() {
            assert!(Instant::now() < deadline);
            thread::sleep(Duration::from_millis(1));
        }
        let authority = store
            .owner
            .inner
            .node
            .barrier
            .try_write_for(Duration::from_millis(50));
        assert!(authority.is_some(), "management drain held node authority");
        drop(authority);
        assert_eq!(quota.join().unwrap().unwrap_err().code, "BUSY");
        snapshot.check().unwrap();
        assert_eq!(
            tenant.get("docs", "confirmed").unwrap().unwrap()["_rev"],
            ack.rev
        );
    }

#[test]
    fn cached_role_positions_retry_brief_contention_and_bound_a_persistent_lock() {
        let dir = tempfile::tempdir().unwrap();
        let store = Store::open(dir.path(), Options::default()).unwrap();
        let info = store.create_tenant("role-retry").unwrap();
        let tenant = store.tenant(info.id).unwrap();
        let seq = tenant.engine().seq();
        let slot = store.slot(info.id);
        let (send, ready) = std::sync::mpsc::channel();
        let held_slot = slot.clone();
        let holding = thread::spawn(move || {
            let _held = held_slot.lock();
            send.send(()).unwrap();
            thread::sleep(Duration::from_millis(30));
        });
        ready.recv().unwrap();
        assert_eq!(store.cached_replication_positions().unwrap()[0].seq, seq);
        holding.join().unwrap();
        let _held = slot.lock();
        let started = Instant::now();
        assert_eq!(
            store.cached_replication_positions().unwrap_err().code,
            "BUSY"
        );
        assert!(started.elapsed() < Duration::from_secs(1));
    }

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn one_tenant_index_build_cannot_fill_the_maintenance_pool() {
    let dir = tempfile::tempdir().unwrap();
    let store = Store::open(dir.path(), Options::default()).unwrap();
    let a = store.create_tenant("index-busy").unwrap().id;
    let b = store.create_tenant("maintenance-healthy").unwrap().id;
    let tenant = store.tenant(a).unwrap();
    tenant.create_collection("docs").unwrap();
    let secret = "maintenance-isolation-secret";
    let app = http::app(
        store.clone(),
        AuthConfig {
            tokens: vec![Token {
                subject: "admin".into(),
                sha256: http::token_hash(secret),
                tenant: None,
                role: Role::Admin,
            }],
        },
    )
    .unwrap();
    let (entered, ready) = std::sync::mpsc::channel();
    let (release, wait) = std::sync::mpsc::channel();
    let engine = tenant.engine().clone();
    let blocker = std::thread::spawn(move || {
        engine.transact(|_| {
            entered.send(()).unwrap();
            let _ = wait.recv_timeout(std::time::Duration::from_secs(5));
            Ok(())
        })
    });
    ready
        .recv_timeout(std::time::Duration::from_secs(1))
        .unwrap();
    let pending = app.clone();
    let first = tokio::spawn(async move {
        call(
            &pending,
            "POST",
            &format!("/v1/tenants/{a}/collections/docs/indexes"),
            Some(secret),
            json!({"name":"first","fields":[{"field":"/value"}]}),
        )
        .await
    });
    tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    assert!(!first.is_finished());
    for n in 0..3 {
        let response = tokio::time::timeout(
            std::time::Duration::from_secs(1),
            call(
                &app,
                "POST",
                &format!("/v1/tenants/{a}/collections/docs/indexes"),
                Some(secret),
                json!({"name":format!("other-{n}"),"fields":[{"field":"/value"}]}),
            ),
        )
        .await
        .unwrap();
        assert_eq!(response.0, StatusCode::TOO_MANY_REQUESTS, "{}", response.1);
    }
    let response = call(
        &app,
        "POST",
        &format!("/v1/tenants/{b}/backup"),
        Some(secret),
        json!({}),
    )
    .await;
    release.send(()).unwrap();
    blocker.join().unwrap().unwrap();
    assert_eq!(response.0, StatusCode::OK, "{}", response.1);
    assert_eq!(first.await.unwrap().0, StatusCode::OK);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn exhausted_execution_pool_rejects_without_polling_the_body() {
    struct UnreadBody;
    impl axum::body::HttpBody for UnreadBody {
        type Data = axum::body::Bytes;
        type Error = std::convert::Infallible;
        fn poll_frame(
            self: std::pin::Pin<&mut Self>,
            _: &mut std::task::Context<'_>,
        ) -> std::task::Poll<Option<std::result::Result<hyper::body::Frame<Self::Data>, Self::Error>>>
        {
            panic!("rejected request body was polled");
        }
    }
    let dir = tempfile::tempdir().unwrap();
    let store = Store::open(
        dir.path(),
        Options {
            max_http_requests: 1,
            ..Default::default()
        },
    )
    .unwrap();
    let tenant = store
        .tenant(store.create_tenant("execution-busy").unwrap().id)
        .unwrap();
    tenant.create_collection("docs").unwrap();
    let id = tenant.id();
    let secret = "execution-preflight-secret";
    let app = http::app(
        store,
        AuthConfig {
            tokens: vec![Token {
                subject: "admin".into(),
                sha256: http::token_hash(secret),
                tenant: None,
                role: Role::Admin,
            }],
        },
    )
    .unwrap();
    let (entered, ready) = std::sync::mpsc::channel();
    let (release, wait) = std::sync::mpsc::channel();
    let engine = tenant.engine().clone();
    let blocker = std::thread::spawn(move || {
        engine.transact(|_| {
            entered.send(()).unwrap();
            let _ = wait.recv_timeout(std::time::Duration::from_secs(5));
            Ok(())
        })
    });
    ready
        .recv_timeout(std::time::Duration::from_secs(1))
        .unwrap();
    let pending = app.clone();
    let first = tokio::spawn(async move {
        call(
            &pending,
            "PUT",
            &format!("/v1/tenants/{id}/collections/docs/documents"),
            Some(secret),
            json!({"document":{"_key":"confirmed","value":1}}),
        )
        .await
    });
    tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    assert!(!first.is_finished());
    let response = app
        .oneshot(
            Request::builder()
                .method("PUT")
                .uri(format!("/v1/tenants/{id}/collections/docs/documents"))
                .header("authorization", format!("Bearer {secret}"))
                .body(Body::new(UnreadBody))
                .unwrap(),
        )
        .await
        .unwrap();
    release.send(()).unwrap();
    blocker.join().unwrap().unwrap();
    assert_eq!(response.status(), StatusCode::TOO_MANY_REQUESTS);
    assert_eq!(first.await.unwrap().0, StatusCode::OK);
    assert_eq!(
        tenant.get("docs", "confirmed").unwrap().unwrap()["value"],
        1
    );
}
